import json
import re
import sys

organizationRaw = sys.argv[1]
installationRaw = sys.argv[2]
serverRaw = sys.argv[3]
configRaw = sys.argv[4]
osImageRaw = sys.argv[5]
scuRaw = sys.argv[6]
installTargetRaw = sys.argv[7]
overrideRaw = sys.argv[8]
waitRaw = sys.argv[9]
timeoutRaw = sys.argv[10]

organizationName = sys.argv[11]
installationName = sys.argv[12]
serverSelector = sys.argv[13]
configSelector = sys.argv[14]
osImageSelector = sys.argv[15]
scuSelector = sys.argv[16]
errors = []

for raw, clean, label in ((organizationRaw, organizationName, "Device Organization"), (installationRaw, installationName, "Installation Name"), (serverRaw, serverSelector, "Server Name or Serial"), (configRaw, configSelector, "OS Configuration File"), (osImageRaw, osImageSelector, "Operating System Image"), (scuRaw, scuSelector, "SCU or OSDU Image")):
    if raw != clean:
        errors.append(label + " must not contain surrounding whitespace.")

def validate_odata(value, label, maximum):
    if not value or len(value) > maximum or any(ord(ch) < 32 or ch in "&?#%" for ch in value):
        errors.append(label + " must contain 1-" + str(maximum) + " characters and must not contain controls or URL query delimiters.")

validate_odata(organizationName, "Device Organization", 64)
validate_odata(installationName, "Installation Name", 128)
validate_odata(serverSelector, "Server Name or Serial", 128)
validate_odata(configSelector, "OS Configuration File", 128)
validate_odata(osImageSelector, "Operating System Image", 128)
validate_odata(scuSelector, "SCU or OSDU Image", 128)

def strict_bool(value, label):
    normalized = value
    if normalized not in ("true", "false"):
        errors.append(label + " must be a boolean.")
        return False
    return normalized == "true"

def strict_int(value, label):
    try:
        parsed = int(value)
    except Exception:
        errors.append(label + " must be an integer.")
        return 0
    if str(parsed) != value and not (value == "-0" and parsed == 0):
        errors.append(label + " must use canonical integer syntax.")
    return parsed

overrideSecureBoot = strict_bool(overrideRaw, "Override Secure Boot")
waitForCompletion = strict_bool(waitRaw, "Wait for Completion")
waitTimeoutSeconds = strict_int(timeoutRaw, "Wait Timeout Seconds")
if waitForCompletion:
    if waitTimeoutSeconds < 1 or waitTimeoutSeconds > 600:
        errors.append("Wait Timeout Seconds must be from 1 through 600 when Wait for Completion is true.")
elif waitTimeoutSeconds != 0:
    errors.append("Wait Timeout Seconds must remain numeric 0 when Wait for Completion is false.")

allowedFields = {
    "os.PhysicalDisk": {"ObjectType", "ClassId", "Name", "SerialNumber", "StorageControllerSlotId"},
    "os.VirtualDrive": {"ObjectType", "ClassId", "Id", "Name", "StorageControllerSlotId"},
    "os.FibreChannelTarget": {"ObjectType", "ClassId", "InitiatorWwpn", "LunId", "TargetWwpn"},
    "os.IscsiTarget": {"ObjectType", "ClassId", "LunId", "TargetIqn", "VnicMac"}
}
selectedTarget = None
try:
    selectedTarget = json.loads(installTargetRaw)
except Exception:
    errors.append("Install Target must be valid JSON.")

if selectedTarget is not None:
    if not isinstance(selectedTarget, dict) or not selectedTarget:
        errors.append("Install Target must be one non-empty JSON object.")
        selectedTarget = None
    else:
        targetType = selectedTarget.get("ObjectType")
        if targetType not in allowedFields:
            errors.append("Install Target ObjectType must be one concrete supported target; abstract os.SanTarget and response-only types are rejected.")
        elif selectedTarget.get("ClassId") != targetType:
            errors.append("Install Target ClassId must exactly equal its concrete ObjectType.")
        elif set(selectedTarget) - allowedFields[targetType]:
            errors.append("Install Target contains fields outside its exact OpenAPI concrete type.")
        else:
            identityFields = allowedFields[targetType] - {"ObjectType", "ClassId"}
            if not any(field in selectedTarget for field in identityFields):
                errors.append("Install Target must carry at least one schema-defined target identity field.")
            for key in identityFields:
                if key in selectedTarget and key != "LunId":
                    value = selectedTarget[key]
                    if not isinstance(value, str) or not value or value != value.strip() or len(value) > 255 or any(ord(ch) < 32 for ch in value):
                        errors.append("Install Target field " + key + " must be an exact non-empty string without controls.")
            if "LunId" in selectedTarget and (isinstance(selectedTarget["LunId"], bool) or not isinstance(selectedTarget["LunId"], int) or selectedTarget["LunId"] < 0 or selectedTarget["LunId"] > 255):
                errors.append("Install Target LunId must be an integer from 0 through 255.")
            wwpn = re.compile(r"^([0-9a-fA-F]{2}:){7}[0-9a-fA-F]{2}$")
            mac = re.compile(r"^([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}$")
            iqn = re.compile(r"^iqn\.(\d{4}-(0[1-9]|1[0-2]))\.([a-zA-Z0-9]+)([a-zA-Z0-9-.]*):([^,\s']+)$")
            if targetType == "os.FibreChannelTarget":
                if set(selectedTarget) != allowedFields[targetType] or not wwpn.fullmatch(selectedTarget.get("InitiatorWwpn", "")) or not wwpn.fullmatch(selectedTarget.get("TargetWwpn", "")):
                    errors.append("FibreChannelTarget requires exactly both valid WWPNs and LunId.")
            elif targetType == "os.IscsiTarget":
                if set(selectedTarget) != allowedFields[targetType] or not iqn.fullmatch(selectedTarget.get("TargetIqn", "")) or not mac.fullmatch(selectedTarget.get("VnicMac", "")):
                    errors.append("IscsiTarget requires exactly valid TargetIqn, VnicMac, and LunId.")

if selectedTarget is None:
    selectedTarget = {}
selectedInstallTargetJson = json.dumps(selectedTarget, sort_keys=True, separators=(",", ":"))
selectedInstallTargetType = selectedTarget.get("ObjectType", "")

escapedOrganizationName = sys.argv[11].replace("'", "''")
escapedInstallationName = sys.argv[12].replace("'", "''")
escapedServerSelector = sys.argv[13].replace("'", "''")
escapedConfigSelector = sys.argv[14].replace("'", "''")
escapedOsImageSelector = sys.argv[15].replace("'", "''")
escapedScuSelector = sys.argv[16].replace("'", "''")

serverApiUrlTemplate = "/api/v1/compute/PhysicalSummaries?$filter=(Name eq '" + escapedServerSelector + "' or Serial eq '" + escapedServerSelector + "') and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,Serial,Model,SourceObjectType,ObjectType,ClassId,PermissionResources"
configApiUrlTemplate = "/api/v1/os/ConfigurationFiles?$filter=(Name eq '" + escapedConfigSelector + "' or Moid eq '" + escapedConfigSelector + "') and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,ObjectType,ClassId,PermissionResources"
imageApiUrlTemplate = "/api/v1/softwarerepository/OperatingSystemFiles?$filter=(Name eq '" + escapedOsImageSelector + "' or Moid eq '" + escapedOsImageSelector + "') and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,ObjectType,ClassId,PermissionResources"
scuApiUrlTemplate = "/api/v1/firmware/ServerConfigurationUtilityDistributables?$filter=(Name eq '" + escapedScuSelector + "' or Moid eq '" + escapedScuSelector + "') and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,ObjectType,ClassId,PermissionResources"
duplicateApiUrlTemplate = "/api/v1/os/Installs?$filter=Name eq '" + escapedInstallationName + "' and Organization.Moid eq '{organizationMoid}'&$select=Moid,Name,OperState,ObjectType,ClassId,Organization,Server"

preparationStatus = "invalid" if errors else "ready"
preparationMessage = " ".join(errors) if errors else "All inputs, JSON target shape, branch-independent constraints, wait bounds, and OData escaping were validated."
preparationResultJson = json.dumps({"validated": not errors, "errors": errors, "deviceOrganization": organizationName, "installationName": installationName, "serverSelector": serverSelector, "configurationSelector": configSelector, "operatingSystemImageSelector": osImageSelector, "scuSelector": scuSelector, "selectedInstallTarget": selectedTarget, "overrideSecureBoot": overrideSecureBoot, "waitForCompletion": waitForCompletion, "waitTimeoutSeconds": waitTimeoutSeconds, "installMethod": "vMedia", "acceptedVersusCompletedSemantics": True, "answersAndCredentialsExcluded": True}, separators=(",", ":"))
helperReady = preparationStatus in ("invalid", "ready") and bool(preparationMessage and preparationResultJson) and (preparationStatus != "ready" or all((serverApiUrlTemplate, configApiUrlTemplate, imageApiUrlTemplate, scuApiUrlTemplate, duplicateApiUrlTemplate, selectedInstallTargetType)))
if not helperReady:
    raise ValueError("Validation did not produce its complete readiness contract.")

import json
import re
import sys

# HTTP evidence is independent from strict organization identity inspection.
# The connector contract supplies an integral HTTP status and Boolean success.
try:
    httpStatus = int(sys.argv[4])
except (ValueError, TypeError):
    httpStatus = 0
requestSucceeded = sys.argv[5].strip().lower() == "true"
if not requestSucceeded or httpStatus != 200:
    statusCode = httpStatus if 300 <= httpStatus < 600 else 502
    lookupStatus = "api-failure"
    message = "Organization lookup API request failed"
    errorMessage = "The organization request failed or returned a non-200 response."
    organizationMoid, organizationJson, inspectionComplete = "", "{}", False
    safeCode, safeMessage = "", ""
    try:
        payload = json.loads(sys.argv[1])
        # Preserve the native String projection used by the old safe allowlists.
        def text(value):
            return value if isinstance(value, str) else json.dumps(value, separators=(",", ":"), ensure_ascii=False)
        code = text(payload["Code"]) if isinstance(payload, dict) and "Code" in payload else ""
        detail = text(payload["Message"]) if isinstance(payload, dict) and "Message" in payload else ""
        if re.fullmatch(r"[A-Za-z0-9_.:-]{1,128}", code):
            safeCode = code
        if re.fullmatch(r"[A-Za-z0-9 _.,:()/+\-]{1,500}", detail) and not re.search(r"authorization|password|secret|token|api.?key|bearer|https?://", detail, re.IGNORECASE):
            safeMessage = detail
    except Exception:
        pass
    if safeMessage:
        errorMessage = safeMessage
    resultJson = json.dumps({"status":"api-failure", "upstreamStatus":httpStatus, "Code":safeCode, "Message":safeMessage}, separators=(",", ":"))
else:
    import json
    import re
    import sys
    statusCode, lookupStatus, message = 502, "invalid-response", "Organization response is invalid"
    organizationMoid, organizationJson = "", "{}"
    inspectionComplete = False
    try:
        payload = json.loads(sys.argv[1])
        if not isinstance(payload, dict): raise ValueError("Organization response must be an object")
        count, rows = payload.get("Count"), payload.get("Results")
        if isinstance(count, bool) or not isinstance(count, int) or count < 0: raise ValueError("Count must be a nonnegative integer")
        if not isinstance(rows, list): raise ValueError("Results must be an array")
        if count != len(rows): raise ValueError("Count and Results length differ; the bounded page is incomplete")
        if count > 2: raise ValueError("Count exceeds the two-row lookup bound")
        if count == 0: statusCode, lookupStatus, message = 404, "not-found", "No organization matched the exact requested name"
        elif count != 1: statusCode, lookupStatus, message = 409, "ambiguous", "More than one organization matched the exact requested name"
        else:
            item = rows[0]
            if not isinstance(item, dict) or item.get("Name") != sys.argv[2]: raise ValueError("Organization Name does not match exactly")
            if item.get("ObjectType") != "organization.Organization" or item.get("ClassId") != "organization.Organization": raise ValueError("Organization discriminators do not match")
            moid = item.get("Moid")
            pattern = r"[0-9a-fA-F]{24}" if sys.argv[3] == "Hex24" else r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}"
            if not isinstance(moid, str) or re.fullmatch(pattern, moid) is None: raise ValueError("Organization Moid is missing or malformed")
            organizationMoid = moid
            projected = {key:item[key] for key in ("Moid", "Name", "ObjectType", "ClassId")}
            organizationJson = json.dumps(projected, separators=(",", ":"))
            resultJson = json.dumps({"Count":1,"Results":[projected]}, separators=(",", ":"))
            statusCode, lookupStatus, message = 200, "exact", "Organization resolved exactly"
        inspectionComplete = True
    except Exception as exc:
        statusCode, lookupStatus, message, inspectionComplete = 502, "invalid-response", str(exc), True
    errorMessage = "" if statusCode == 200 else message
    if statusCode != 200: resultJson = json.dumps({"status":lookupStatus,"error":message}, separators=(",", ":"))

legacyOsOrganizationResultJson = json.dumps({"status":lookupStatus,"message":message,"organizationName":sys.argv[2],"organizationMoid":organizationMoid or None}, separators=(",", ":"))

import json
import re
import sys
payload = json.loads(sys.argv[1]); selector = sys.argv[2]; organizationMoid = sys.argv[3]
values = payload.get("Results")
if not isinstance(values, list): raise ValueError("Server response is missing Results")
def safe_moid(v): return isinstance(v, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", v) is not None
def org_present(values):
    return isinstance(values, list) and any(isinstance(v, dict) and v.get("Moid") == organizationMoid and v.get("ObjectType") in (None, "organization.Organization") for v in values)
serverMoid = ""; sourceObjectType = ""; serverModel = ""; validTargetsRequestJson = ""
if len(values) == 0:
    serverStatus = "not-found"; serverMessage = "No exact organization-scoped PhysicalSummary matched server Name or Serial."
elif len(values) > 1:
    serverStatus = "ambiguous"; serverMessage = "Multiple organization-scoped PhysicalSummaries matched server Name or Serial."
else:
    item = values[0]; problems = []
    if not isinstance(item, dict): problems.append("Server result is not an object.")
    else:
        if item.get("Name") != selector and item.get("Serial") != selector: problems.append("Returned server matches neither exact Name nor exact Serial.")
        if item.get("ObjectType") != "compute.PhysicalSummary" or item.get("ClassId") != "compute.PhysicalSummary": problems.append("PhysicalSummary discriminators are invalid.")
        if not safe_moid(item.get("Moid")): problems.append("Server Moid is missing or unsafe.")
        if item.get("SourceObjectType") not in ("compute.Blade", "compute.RackUnit"): problems.append("PhysicalSummary SourceObjectType is not concrete compute.Blade or compute.RackUnit.")
        if not isinstance(item.get("Model"), str) or not item.get("Model").strip(): problems.append("Server Model is missing.")
        if not org_present(item.get("PermissionResources")): problems.append("Returned server does not retain the exact organization permission relationship.")
    if problems:
        serverStatus = "invalid"; serverMessage = " ".join(problems)
    else:
        serverStatus = "exact"; serverMessage = "Exactly one concrete Blade/RackUnit server identity was validated."
        serverMoid = item["Moid"]; sourceObjectType = item["SourceObjectType"]; serverModel = item["Model"]
        validTargetsRequestJson = json.dumps({"ObjectType":"os.ValidInstallTarget","ClassId":"os.ValidInstallTarget","Servers":[{"Moid":serverMoid,"ObjectType":sourceObjectType,"ClassId":"mo.MoRef"}]}, separators=(",", ":"))
serverResultJson = json.dumps({"status":serverStatus,"message":serverMessage,"serverSelector":selector,"serverMoid":serverMoid or None,"sourceObjectType":sourceObjectType or None,"serverModel":serverModel or None,"organizationMoid":organizationMoid}, separators=(",", ":"))
helperReady = serverStatus in ("not-found","ambiguous","invalid","exact") and bool(serverMessage and serverResultJson) and (serverStatus != "exact" or all((serverMoid,sourceObjectType,serverModel,validTargetsRequestJson)))
if not helperReady:
    raise ValueError("Validation did not produce its complete readiness contract.")

# Retain complete ordered terminal-state publication with its inspector.
import re
terminalCase1Matched = False
terminalCase1StatusCode = ""
terminalCase1StatusMessage = ""
terminalCase1ErrorMessage = ""
terminalCase1ResultJson = ""
terminalCase1CompletionMessage = ""
if (serverStatus == 'not-found'):
    terminalCase1Matched = True
    terminalCase1StatusCode = '404'
    terminalCase1StatusMessage = 'Server was not found'
    terminalCase1ErrorMessage = (str(serverMessage).lower() if isinstance(serverMessage, bool) else str(serverMessage))
    terminalCase1ResultJson = (str(serverResultJson).lower() if isinstance(serverResultJson, bool) else str(serverResultJson))
    terminalCase1CompletionMessage = 'Server was not found'
elif ((serverStatus == 'ambiguous') or (serverStatus == 'invalid')):
    terminalCase1Matched = True
    terminalCase1StatusCode = '409'
    terminalCase1StatusMessage = 'Server resolution is ambiguous or invalid'
    terminalCase1ErrorMessage = (str(serverMessage).lower() if isinstance(serverMessage, bool) else str(serverMessage))
    terminalCase1ResultJson = (str(serverResultJson).lower() if isinstance(serverResultJson, bool) else str(serverResultJson))
    terminalCase1CompletionMessage = 'Server resolution is ambiguous or invalid'

import json
import re
import sys
payload = json.loads(sys.argv[1]); selected = json.loads(sys.argv[2]); serverMoid = sys.argv[3]; sourceObjectType = sys.argv[4]
def safe_moid(v): return isinstance(v, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", v) is not None
def rel_matches(v): return isinstance(v, dict) and v.get("Moid") == serverMoid and v.get("ObjectType") == sourceObjectType and v.get("ClassId") in (None, "mo.MoRef", sourceObjectType)
problems = []
if not isinstance(payload, dict):
    problems.append("ValidInstallTargets response is not an object.")
else:
    if payload.get("ObjectType") != "os.ValidInstallTarget" or payload.get("ClassId") != "os.ValidInstallTarget": problems.append("ValidInstallTargets discriminators are invalid.")
    servers = payload.get("Servers")
    if not isinstance(servers, list) or len(servers) != 1 or not rel_matches(servers[0]): problems.append("ValidInstallTargets did not retain exactly the selected concrete server relationship.")
    if payload.get("Error") not in (None, "", {}, []): problems.append("ValidInstallTargets returned a non-empty Error.")

fieldMap = {
  "os.PhysicalDiskResponse": ("os.PhysicalDisk", ("Name","SerialNumber","StorageControllerSlotId")),
  "os.VirtualDriveResponse": ("os.VirtualDrive", ("Id","Name","StorageControllerSlotId")),
  "os.PhysicalDisk": ("os.PhysicalDisk", ("Name","SerialNumber","StorageControllerSlotId")),
  "os.VirtualDrive": ("os.VirtualDrive", ("Id","Name","StorageControllerSlotId")),
  "os.FibreChannelTarget": ("os.FibreChannelTarget", ("InitiatorWwpn","LunId","TargetWwpn")),
  "os.IscsiTarget": ("os.IscsiTarget", ("LunId","TargetIqn","VnicMac"))
}
containers = ["InstallTargets","E1sNvme","E3sNvme","M2Jbod","M2NvmeRaidJbod","M2NvmeRaidVirtualDrives","M2VirtualDrives","MraidJbod","MraidVirtualDrives","MstorNvme","U2Nvme"]
candidates = {}
sourceCounts = {}
for container in containers:
    entries = payload.get(container)
    if entries is None: continue
    if not isinstance(entries, list):
        problems.append(container + " is not an array."); continue
    for index, entry in enumerate(entries):
        if not isinstance(entry, dict):
            problems.append(container + " contains a non-object target."); continue
        responseType = entry.get("ObjectType")
        if responseType == "os.SanTarget":
            problems.append(container + " returned abstract os.SanTarget, which cannot be safely submitted."); continue
        if responseType not in fieldMap:
            problems.append(container + " returned unsupported target discriminator " + str(responseType) + "."); continue
        if entry.get("ClassId") != responseType:
            problems.append(container + " target ClassId does not equal ObjectType."); continue
        requestType, fields = fieldMap[responseType]
        normalized = {"ObjectType":requestType,"ClassId":requestType}
        for field in fields:
            if field in entry and entry[field] not in (None, ""):
                normalized[field] = entry[field]
        if len(normalized) == 2:
            problems.append(container + " target carries no usable schema-defined identity fields."); continue
        if "LunId" in normalized and (isinstance(normalized["LunId"], bool) or not isinstance(normalized["LunId"], int) or normalized["LunId"] < 0 or normalized["LunId"] > 255):
            problems.append(container + " target LunId is invalid."); continue
        if any(not isinstance(v, str) or not v or v != v.strip() for k,v in normalized.items() if k not in ("ObjectType","ClassId","LunId")):
            problems.append(container + " target contains an invalid string identity field."); continue
        key = json.dumps(normalized, sort_keys=True, separators=(",", ":"))
        candidates[key] = normalized
        sourceCounts[key] = sourceCounts.get(key, 0) + 1

selectedKey = json.dumps(selected, sort_keys=True, separators=(",", ":"))
validatedInstallTargetJson = ""
if problems:
    targetStatus = "invalid"; targetMessage = " ".join(problems)
elif not candidates:
    targetStatus = "no-targets"; targetMessage = "ValidInstallTargets returned no schema-supported concrete target."
elif selectedKey not in candidates:
    targetStatus = "no-match"; targetMessage = "Selected Install Target does not exactly match one normalized concrete target returned for this server."
else:
    targetStatus = "match"; targetMessage = "Selected Install Target exactly matches one unique normalized concrete target returned for this server."
    validatedInstallTargetJson = selectedKey
targetResultJson = json.dumps({"status":targetStatus,"message":targetMessage,"serverMoid":serverMoid,"serverObjectType":sourceObjectType,"selectedInstallTarget":selected,"validUniqueTargets":list(candidates.values()),"sourceOccurrences":sourceCounts.get(selectedKey,0),"crossContainerDuplicatesDeduplicated":True,"currentSchemaResponseNormalization":{"os.PhysicalDiskResponse":"os.PhysicalDisk","os.VirtualDriveResponse":"os.VirtualDrive"},"abstractSanTargetRejected":True}, separators=(",", ":"))
helperReady = targetStatus in ("invalid","no-targets","no-match","match") and bool(targetMessage and targetResultJson) and (targetStatus != "match" or bool(validatedInstallTargetJson))
if not helperReady:
    raise ValueError("Validation did not produce its complete readiness contract.")

# Retain complete ordered terminal-state publication with its inspector.
import re
terminalCase2Matched = False
terminalCase2StatusCode = ""
terminalCase2StatusMessage = ""
terminalCase2ErrorMessage = ""
terminalCase2ResultJson = ""
terminalCase2CompletionMessage = ""
if (targetStatus == 'invalid'):
    terminalCase2Matched = True
    terminalCase2StatusCode = '502'
    terminalCase2StatusMessage = 'ValidInstallTargets response failed validation'
    terminalCase2ErrorMessage = (str(targetMessage).lower() if isinstance(targetMessage, bool) else str(targetMessage))
    terminalCase2ResultJson = (str(targetResultJson).lower() if isinstance(targetResultJson, bool) else str(targetResultJson))
    terminalCase2CompletionMessage = 'ValidInstallTargets response failed validation'
elif (targetStatus == 'no-targets'):
    terminalCase2Matched = True
    terminalCase2StatusCode = '404'
    terminalCase2StatusMessage = 'No valid install target is available'
    terminalCase2ErrorMessage = (str(targetMessage).lower() if isinstance(targetMessage, bool) else str(targetMessage))
    terminalCase2ResultJson = (str(targetResultJson).lower() if isinstance(targetResultJson, bool) else str(targetResultJson))
    terminalCase2CompletionMessage = 'No valid install target is available'
elif (targetStatus == 'no-match'):
    terminalCase2Matched = True
    terminalCase2StatusCode = '422'
    terminalCase2StatusMessage = 'Selected Install Target is not allowed for this server'
    terminalCase2ErrorMessage = (str(targetMessage).lower() if isinstance(targetMessage, bool) else str(targetMessage))
    terminalCase2ResultJson = (str(targetResultJson).lower() if isinstance(targetResultJson, bool) else str(targetResultJson))
    terminalCase2CompletionMessage = 'Selected Install Target is not allowed for this server'

import json
import re
import sys
prepared = json.loads(sys.argv[1]); organization = json.loads(sys.argv[2]); server = json.loads(sys.argv[3]); config = json.loads(sys.argv[4]); image = json.loads(sys.argv[5]); scu = json.loads(sys.argv[6]); targetResult = json.loads(sys.argv[7]); target = json.loads(sys.argv[8])
def safe_moid(v): return isinstance(v, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", v) is not None
problems = []
if not prepared.get("validated") or prepared.get("installMethod") != "vMedia": problems.append("Prepared input contract is invalid.")
if organization.get("status") != "exact" or not safe_moid(organization.get("organizationMoid")): problems.append("Organization contract is not exact.")
if server.get("status") != "exact" or server.get("sourceObjectType") not in ("compute.Blade","compute.RackUnit") or not safe_moid(server.get("serverMoid")): problems.append("Server contract is not exact and concrete.")
expectedTypes = ((config,"os.ConfigurationFile"),(image,"softwarerepository.OperatingSystemFile"),(scu,"firmware.ServerConfigurationUtilityDistributable"))
for resource, expected in expectedTypes:
    if resource.get("status") != "exact" or resource.get("objectType") != expected or not safe_moid(resource.get("resourceMoid")): problems.append("Resolved resource contract is not exact for " + expected + ".")
if targetResult.get("status") != "match" or targetResult.get("selectedInstallTarget") != target or target.get("ObjectType") not in ("os.PhysicalDisk","os.VirtualDrive","os.FibreChannelTarget","os.IscsiTarget") or target.get("ClassId") != target.get("ObjectType"): problems.append("Selected target contract is not an exact concrete ValidInstallTargets match.")
if problems: raise ValueError(" ".join(problems))
request = {
 "ObjectType":"os.Install", "ClassId":"os.Install", "Name":prepared["installationName"],
 "Organization":{"Moid":organization["organizationMoid"],"ObjectType":"organization.Organization","ClassId":"mo.MoRef"},
 "Server":{"Moid":server["serverMoid"],"ObjectType":server["sourceObjectType"],"ClassId":"mo.MoRef"},
 "ConfigurationFile":{"Moid":config["resourceMoid"],"ObjectType":"os.ConfigurationFile","ClassId":"mo.MoRef"},
 "Image":{"Moid":image["resourceMoid"],"ObjectType":"softwarerepository.OperatingSystemFile","ClassId":"mo.MoRef"},
 "OsduImage":{"Moid":scu["resourceMoid"],"ObjectType":"firmware.ServerConfigurationUtilityDistributable","ClassId":"mo.MoRef"},
 "InstallTarget":target, "InstallMethod":"vMedia", "OverrideSecureBoot":bool(prepared.get("overrideSecureBoot"))
}
requestJson = json.dumps(request, sort_keys=True, separators=(",", ":"))
requestResultJson = json.dumps({"validated":True,"requestObjectType":"os.Install","installMethod":"vMedia","organizationMoid":organization["organizationMoid"],"serverMoid":server["serverMoid"],"serverObjectType":server["sourceObjectType"],"configurationFileMoid":config["resourceMoid"],"operatingSystemImageMoid":image["resourceMoid"],"osduImageMoid":scu["resourceMoid"],"installTarget":target,"answersOmitted":True,"additionalParametersOmitted":True}, separators=(",", ":"))
helperReady = bool(requestJson and requestResultJson) and "Answers" not in request and "AdditionalParameters" not in request
if not helperReady:
    raise ValueError("Validation did not produce its complete readiness contract.")

import json
